def setup_ems(**kwargs):
    """
    This keyword is used to setup EMSSIM or Netact

    *Parameters:* \n

    *Common*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |

    *EMSSIM*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | enb_id | Optional | The eNB ID |
    | wait_tcp_connected | False | wait only for bts TCP connection. If value is True then do |  |
    |                    |       | not wait for OAM connection and discovery |  |
    | wait_connected | True | wait for bts OAM connection. If False then do not wait for discovery |
    | wait_discovered | True | Wait for BTS to be discovered |
    | timeout | 180  | Timeout to for Ems session to start |
    | bts_timeout | 180 | Timeout for bts connection and discovery to be completed |
    | ne3s_activate | True | Use Netact NE3S and activate COAM. If variable OM_TYPE=BTSMED |  |
    |               |      | then activate SOAM instead |  |
    | kwargs | Optional | Additional set of params for start |

    *NETACT*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | alias | Default | Name of the execution context |

    *NOM*
    NOM does not require alias

    *Returns*:

    *Raises*:

    *Examples*
    | Setup Ems | config_device=emssim1 |

    *Configurations  Needed* \n
    `testline_config` sections:
    "ems"


    """
    config_device = kwargs.get('config_device')
    return EmsFactory().get_instance(config_device).setup_ems(**kwargs)


def cm_upload(**kwargs):
    """
    Uploads configuration data from the network. The operation is used for uploading network \n
    element configuration data and storing it as actual configuration to the NetAct Configurator
    \n database.

    *Parameters:*

    *EMSSIM*
    Not valid for EMS. Hence keyword call for EMS instance is made dummy

    *NETACT*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
    | sran_bts_hw_content_in_use | None | Indicates if Single RAN base station (SBTS, MRBTS) |  |
    |                            |      | hardware inventory objects are handled with an upload |  |
    |                            |      | operation. |  |
    | ignore_errors | False | If True, shows warnings instead of raising errors when operation |  |
    |               |       | fails. |  |
    | dist_name | PLMN-PLMN/MRBTS-<btsid> | Specifies the scope of the operation. |  |
    | timeout | 7200 |  Operation timeout. |  |
    | alias | default | Name of execution context |  |

    *Returns*:

    *Raises*:

    """
    config_device = kwargs.pop('config_device')
    return EmsFactory().get_instance(config_device).cm_upload(**kwargs)


def export(**kwargs):
    """
    *Description:* \n
    Netact and NOM: Exports data from Configurator and saves configuration to local_dir/file_name if local_dir is
    \n specified (else it returns data as string).
    EMSSIM: Requests file upload of specific file type and saves the configuration to home/flexi**/UPLOADS/ folder.
            Similar to file_upload operation.

    *Parameters:* \n
    *Common*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
    | alias | None | Name of execution context |  |

    *EMSSIM*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | file_name | Mandatory | Type of to-be-uploaded file. hwConfigurationFile, configurationPlanFile, logFile, |  |
    |  |  | swFile, licFile, measurementFile, rnwConfigurationPlanFile, signalingPlanFile, ipPlanFile, alarmFile, |  |
    |  |  | combinedSiteConfigurationPlanFile, allConfigurationPlanFile, locationLock, testResultFile, |  |
    |  |  | autoConfReport, connectedFapInfoFile, measurementPlanFile, rnwMetadataFile, topologyFile, atmPlanFile, |  |
    |  |  | subTopologyFile, togglingParFile, troubleShootingData, fapTmplFile, ipRangeFile, ipSecPlanFile, |  |
    |  |  | fapConfiguredPlanFile, fapActivatedPlanFile, fgwPlanFileWithoutMacroCells, fgwCertExpiryFile, |  |
    |  |  | fapCertExpiryFile, fapScanResultFile, fgwFcodesPlanFile, fgwInseePlanFile, fgwMacroDBPlanFile, |  |
    |  |  | fgwFapsIpSecConnFailureFile, fgwSecurityClonedHnbFile |  |
    | enb_id | 1 | The eNB ID |  |

    *NETACT and NOM*
    | *Arguments* | *Default* | *Comments* |
    | file_name | exported_actual_config.xml | Exported file name |
    | dist_names | PLMN-PLMN/MRBTS-<btsid> | The scope of the export |

    *NETACT*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | operation_type | actual | Type of export, can be plan/actual/reference/template/siteTemplate |  |
    | file_format | RAML2 | Exported file format, can be RAML2/CSV/XLSX |  |
    | class_filter | ALL_MOCS | |  |
    | class_filter_exclude | None | |  |
    | class_filter_include | None | |  |
    | plan_name | None |  |  |
    | ui_values | False | |  |
    | include_site_info | False | |  |
    | include_maintenance_region_info | False | |  |
    | use_qualified_class_abbreviation | False | |  |
    | ignore_errors | False | Ignores Errors if True |  |
    | timeout | 7200 | Timeout |  |

    *NOM*
    Only parameters mentioned in common sections are needed.
    *Returns:* string, configuration data

    *Raises:*

    *Example:*

    Netact: \n
    | export | config_device=netact_device1 | file_name=hwConfigurationFile  |

    EMSSIM: \n
    | export | config_device=ems_device1  | file_name=exported_actual_config.xml |

    """
    config_device = kwargs.pop('config_device')
    return EmsFactory().get_instance(config_device).export(**kwargs)


def import_(**kwargs):
    """
    *Description:* \n
    Netact and NOM: Imports plan given as file_name located in local_dir as NetAct plan_name.
    EMSSIM: Requests file download from /home/flexi**/UPLOADS/** into EnodeB of specific file type.
            Similar to file_download operation.

    *Parameters:* \n
    *Common*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | config_device | Mandatory | Device name according to testline_config.json | `testline_config` |
    | alias | default | Name of execution context |  |

    *EMSSIM*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | file_name | Mandatory | This arg or inputFile arg must be specified |  |
    | path | Mandatory | Path to file on local filesystem (to be downloaded into eNodeB) |  |
    | plan_id | Mandatory | Configuration change plan number [0..4294967295] In case of |  |
    |  |  | allConfigurationPlanFile(12) file type, this parameter should be identical to the id of attribute |  |
    |  |  | value inside the cmData element of to-be-downloaded XML file |  |
    | activate  | 0 | The eNB ID |  |
    | enb_id | Optional | The eNB ID |  |

    *NETACT*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | file_name | Mandatory | Specifies the file name. This parameter (together with local_dir) or remote_file_path |  |
    |  |  | must be specified. If both are provided then the remote_file_path parameter is used. If local_dir is |  |
    |  |  | not provided then given file_name must exist on Netact under default import directory. |  |
    | local_dir | None | Path to the directory where file_name is present - Mandatory if given file_name is present |  |
    |  |  | in local device and not in Netact | |
    | remote_file_path | None | Full file path, Mandatory if file to be imported is inside Netact file system. |  |
    |  |  | This parameter or the file_name parameter (together with local_dir) must be specified. If both are |  |
    |  |  | specified then the remote_file_path is used. |  |
    | plan_name | The plan name from inside RAML2 file | (string) - Plan name on netact |
    |  |  | For NOM, this "plan_name" will be chosen to select parameters from "import_" section of testline_config |

    | file_format | RAML2 | Can be RAML2/CSV/XLSX |  |
    | operation_type | plan |  Specifies the type of import operation (plan/template/site/siteTemplate). |  |
    | ui_values | None | bool, Specifies if the file should be imported with UI parameters values. Default value is |  |
    |  |  | Internal values. |  |
    | use_object_operation | None | If true, object operation (create, update, delete) is set |  |
    |  |  | as defined in the import file. If true and operation is missing from the import file, |  |
    |  |  | then object is not imported. If false, then operation is set based on object |  |
    |  |  | existence in the NetAct database |  |
    | ignore_errors | True | If True, Errors are not raised, only warnings |  |
    | timeout | 7200 | Operation timeout |  |

    *NOM*
    | *Arguments* | *Default Value* | *Comments* | *Config Ref* |
    | input_file | Mandatory | (string) - full file path. Either this or the fileName arg are mandatory. |
    | plan_name | The plan name from inside RAML2 file | (string) - Plan name on netact |
    |  |  | For NOM, this "plan_name" will be chosen to select parameters from "import_" section of testline_config |

    | description | "" | User can optionally provide a description for content and/or purpose of this plan. |  |
    |  |  |  |`testline_config` |
    | overwrite | False | By default importing plan with name already existing in NOM will be refused. |  |
    |  |  |  |`testline_config` |
    | plan_type | "" | This parameter is indicating what is the type of the plan. Plan type is used to |  |
    |  |  |  |`testline_config` |
    |  |  | differentiate plans for different use cases in NOM UI. |  |
    *Returns:* None

    *Raises:*

    *Example:*

    Netact: \n
    | import | config_device=netact_device1 | file_name=hwConfigurationFile  |

    EMSSIM: \n
    | import | config_device=ems_device1  | path=/home/flexi57/UPLOADS/CUPL_BTSA_57.xml |
    |  | file_name=allconfigurationplanfile | plan_id=3221225472 |

    """
    config_device = kwargs.pop('config_device')
    return EmsFactory().get_instance(config_device).import_(**kwargs)


